/* {lane, board} per zone: idx4 = the palette entry of each texel, 4 bits,
 * low nibble first (tr_ztex_at(); the scene unpacks a bound texture to
 * r3d.h's entry * 2 bytes), pal = the RGB565 entries (<= 16), cnt =
 * texels per entry (the shoulder detail fade's mean), nb[k * 16 + j] = the
 * share (of 65535) of entry j in the 5 x 5 boxes round those of entry k
 * (the lanes' detail fade, r3d_scene.c fade_detail()), avg = the far road's
 * three rows (byte offsets into avg_pal, avg_n <= 32 colours; r3d_scene.c
 * avg_bind()). */
typedef struct {
	const uint8_t  *idx4;
	const uint16_t *pal;
	const uint16_t *cnt;
	uint32_t        n;
	const uint16_t *nb;
	const uint8_t  *avg;
	const uint16_t *avg_pal;
	uint32_t        avg_n;
} tr_ztex_t;
